using HRMS.Application.DTOs.Payroll;
using HRMS.Application.Services;
using HRMS.Domain.Entities;
using HRMS.Domain.Enums;
using HRMS.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;
using HRMS.Tests.TestSupport;

namespace HRMS.Tests;

internal static class PayrollAdjustmentsProviderAcceptance
{
    public static async Task RunAsync(HrmsDbContext db, TestTenantContext tenantContext, DatabaseProviderType provider)
    {
        var tenantId = Guid.NewGuid(); var employeeId = Guid.NewGuid(); var makerUserId = Guid.NewGuid(); var checkerUserId = Guid.NewGuid(); tenantContext.TenantId = tenantId; tenantContext.UserId = makerUserId;
        await using var transaction = await db.Database.BeginTransactionAsync();
        try
        {
            var periodId = Guid.NewGuid(); var runId = Guid.NewGuid(); var runEmployeeId = Guid.NewGuid(); var resultId = Guid.NewGuid(); var structureId = Guid.NewGuid(); var versionId = Guid.NewGuid(); var assignmentId = Guid.NewGuid(); db.Users.AddRange(new User { Id = makerUserId, TenantId = tenantId, Email = $"{makerUserId:N}@provider.test", FirstName = "Provider", LastName = "Maker" }, new User { Id = checkerUserId, TenantId = tenantId, Email = $"{checkerUserId:N}@provider.test", FirstName = "Provider", LastName = "Checker" });
            db.Tenants.Add(new Tenant { Id = tenantId, TenantCode = $"RPA{tenantId:N}"[..12], TenantName = $"Adjustments {provider}", Host = $"{tenantId:N}.adjustments.test", ShardKey = tenantId.ToString("N"), Status = TenantStatus.Active }); db.Employees.Add(new Employee { Id = employeeId, TenantId = tenantId, EmployeeCode = $"RPA-{employeeId:N}"[..12], FirstName = "Provider", LastName = "Adjustment", Email = $"{employeeId:N}@provider.test", DateOfJoining = new(2024, 1, 1), Status = EmployeeStatus.Active }); db.SalaryStructures.Add(new SalaryStructure { Id = structureId, TenantId = tenantId, Code = $"RPA-{provider}-STRUCT", Name = "Provider structure", IsActive = true }); db.SalaryStructureVersions.Add(new SalaryStructureVersion { Id = versionId, TenantId = tenantId, SalaryStructureId = structureId, EffectiveFrom = new(2026, 1, 1), IsActive = true }); db.EmployeeSalaryAssignments.Add(new EmployeeSalaryAssignment { Id = assignmentId, TenantId = tenantId, EmployeeId = employeeId, SalaryStructureId = structureId, SalaryStructureVersionId = versionId, EffectiveFrom = new(2026, 1, 1), MonthlyCtc = 10000, CurrencyCode = "INR", Status = EmployeeSalaryAssignmentStatus.Active }); db.PayrollPeriods.Add(new PayrollPeriod { Id = periodId, TenantId = tenantId, Code = $"RPA-{provider}", Name = "Provider adjustment period", PeriodType = PayrollPeriodType.Monthly, StartDate = new(2026, 9, 1), EndDate = new(2026, 9, 30), PayDate = new(2026, 10, 5), FiscalYear = 2026, PeriodNumber = 9, Status = PayrollPeriodStatus.Open }); db.PayrollRuns.Add(new PayrollRun { Id = runId, TenantId = tenantId, PayrollPeriodId = periodId, RunNumber = $"RPA-{provider}-RUN", RunType = PayrollRunType.Regular, Status = PayrollRunStatus.Finalized }); db.PayrollRunEmployees.Add(new PayrollRunEmployee { Id = runEmployeeId, TenantId = tenantId, PayrollRunId = runId, EmployeeId = employeeId, EmployeeSalaryAssignmentId = assignmentId, SalaryStructureId = structureId, SalaryStructureVersionId = versionId, EmploymentSnapshotDate = new(2026, 9, 30), IsEligible = true, Status = PayrollRunEmployeeStatus.Eligible }); db.PayrollResults.Add(new PayrollResult { Id = resultId, TenantId = tenantId, PayrollRunId = runId, PayrollRunEmployeeId = runEmployeeId, EmployeeId = employeeId, EmployeeSalaryAssignmentId = assignmentId, SalaryStructureId = structureId, SalaryStructureVersionId = versionId, CalculationAttemptId = Guid.NewGuid(), PeriodStartDate = new(2026, 9, 1), PeriodEndDate = new(2026, 9, 30), EmploymentSnapshotDate = new(2026, 9, 30), CalendarDays = 30, EligibleDays = 30, CurrencyCode = "INR", GrossEarnings = 10000, TotalDeductions = 1000, NetPay = 9000, Status = PayrollResultStatus.Calculated, IsCurrent = true }); db.PayrollResultComponents.Add(new PayrollResultComponent { Id = Guid.NewGuid(), TenantId = tenantId, PayrollResultId = resultId, CalculationAttemptId = Guid.NewGuid(), ComponentCode = "BASE", ComponentName = "Base earning", ComponentType = SalaryComponentType.Earning, CalculationType = SalaryStructureCalculationType.FixedAmount, UnproratedAmount = 10000, ProrationFactor = 1, CalculatedAmount = 10000, IsEarning = true, IsTaxable = true, CalculationSequence = 1, CalculationSource = "ProviderAcceptance" }); await db.SaveChangesAsync();
            var context = tenantContext; var runService = new PayrollRunService(db, context, TimeProvider.System); var service = new PayrollAdjustmentService(db, context, TimeProvider.System, runService);
            var reason = await service.CreateReasonAsync(new PayrollAdjustmentReasonRequest { Code = "MISSED_EARNING", Name = "Missed earning", RequiresComment = true }); Assert.True(reason.Succeeded, reason.Message);
            var request = new PayrollAdjustmentRequest { EmployeeId = employeeId, EffectiveDate = new(2026, 9, 1), ReasonCodeId = reason.Value!.Id, SourceType = "ProviderAcceptance", SourceReferenceId = Guid.NewGuid(), Description = "Provider correction", ComponentCode = "BONUS", Amount = 1000, AdjustmentType = PayrollAdjustmentType.PriorPeriodCorrection, OriginalPayrollRunId = runId, OriginalPayrollResultId = resultId };
            var first = await service.CreateAsync(request); Assert.True(first.Succeeded, first.Message); var retry = await service.CreateAsync(request); Assert.False(retry.Succeeded); Assert.StartsWith("PADJ/2026/", first.Value!.AdjustmentNumber); Assert.True((await db.PayrollCorrectionSnapshots.AnyAsync(x => x.TenantId == tenantId && x.PayrollAdjustmentId == first.Value.Id))); Assert.True((await service.SubmitAsync(first.Value.Id)).Succeeded); context.UserId = checkerUserId; Assert.True((await service.ApproveAsync(first.Value.Id)).Succeeded); Assert.Equal(1, await db.PayrollAdjustmentReasons.CountAsync(x => x.TenantId == tenantId)); Assert.Equal(PayrollAdjustmentStatus.Approved, (await db.PayrollAdjustments.SingleAsync(x => x.Id == first.Value.Id)).Status);
            var offCycle = await service.CreateOffCycleRunAsync(new PayrollOffCycleRunRequest { PayrollPeriodId = periodId, EffectiveDate = new(2026, 10, 5), PaymentDate = new(2026, 10, 5), AdjustmentIds = [first.Value.Id] }); Assert.True(offCycle.Succeeded, offCycle.Message); Assert.Equal(PayrollRunType.OffCycle, offCycle.Value!.RunType); Assert.Equal(PayrollAdjustmentStatus.Scheduled, (await db.PayrollAdjustments.SingleAsync(x => x.Id == first.Value.Id)).Status);
            var reversal = await service.RequestReversalAsync(new PayrollReversalRequest { OriginalPayrollRunId = runId, OriginalPayrollResultId = resultId, Reason = "Provider acceptance reversal" }); Assert.True(reversal.Succeeded, reversal.Message); context.UserId = checkerUserId; var approvedReversal = await service.ApproveReversalAsync(reversal.Value!.Id); Assert.True(approvedReversal.Succeeded, approvedReversal.Message); var processedReversal = await service.ProcessReversalAsync(reversal.Value.Id); Assert.True(processedReversal.Succeeded, processedReversal.Message); Assert.Equal(PayrollReversalStatus.Processed, processedReversal.Value!.Status); Assert.NotNull(processedReversal.Value.ReversalRunId); Assert.True(await db.PayrollAdjustments.AnyAsync(x => x.TenantId == tenantId && x.SourceType == "PayrollReversal" && x.TargetPayrollRunId == processedReversal.Value.ReversalRunId));
            var finalRequest = new PayrollAdjustmentRequest { EmployeeId = employeeId, EffectiveDate = new(2026, 9, 30), ReasonCodeId = reason.Value.Id, SourceType = "ProviderFinalSettlement", SourceReferenceId = Guid.NewGuid(), Description = "Final settlement adjustment", Amount = 250, SettlementMethod = PayrollAdjustmentSettlementMethod.FinalSettlement }; var finalAdjustment = await service.CreateAsync(finalRequest); Assert.True(finalAdjustment.Succeeded, finalAdjustment.Message); Assert.True((await service.SubmitAsync(finalAdjustment.Value!.Id)).Succeeded); context.UserId = checkerUserId; Assert.True((await service.ApproveAsync(finalAdjustment.Value.Id)).Succeeded); var settlementService = new PayrollRetroSettlementService(db, context, TimeProvider.System); var settlement = await settlementService.CreateSettlementAsync(new FinalSettlementRequest { EmployeeId = employeeId, SeparationDate = new(2026, 10, 10), LastWorkingDate = new(2026, 10, 10), SettlementDate = new(2026, 10, 10), CurrencyCode = "INR" }); Assert.True(settlement.Succeeded, settlement.Message); var calculated = await settlementService.CalculateSettlementAsync(settlement.Value!.Id); Assert.True(calculated.Succeeded, calculated.Message); Assert.Contains(calculated.Value!.Lines, x => x.SourceType == "PayrollAdjustment" && x.SourceId == finalAdjustment.Value.Id); Assert.True((await settlementService.ApproveSettlementAsync(settlement.Value.Id)).Succeeded); Assert.True((await settlementService.FinalizeSettlementAsync(settlement.Value.Id)).Succeeded); Assert.True(await db.PayrollAdjustmentApplications.AnyAsync(x => x.TenantId == tenantId && x.PayrollAdjustmentId == finalAdjustment.Value.Id && x.FinalSettlementId == settlement.Value.Id));
            var other = new TestTenantContext(Guid.NewGuid()); Assert.False((await new PayrollAdjustmentService(db, other, TimeProvider.System, runService).GetByIdAsync(first.Value.Id)).Succeeded);
        }
        finally { await transaction.RollbackAsync(); db.ClearChangeTracker(); }
    }
}
